model.en:
Register a SIGTERM/SIGINT handler that flips readiness, drains, then exits under a hard timeout:

let shuttingDown = false;
async function shutdown(sig) {
  if (shuttingDown) return; // idempotent: a 2nd SIGTERM must not re-enter
  shuttingDown = true;
  console.log(`${sig}: draining`);

  ready = false; // (a) fail readiness FIRST so the LB stops sending new traffic

  const force = setTimeout(() => {
    console.error('drain timed out, forcing exit');
    process.exit(1);
  }, 10_000);
  force.unref(); // the timer must not itself keep the loop alive

  try {
    await new Promise((res, rej) =>
      server.close((err) => (err ? rej(err) : res())) // (b) stop accepting, let in-flight finish
    );
    await pool.end(); // (c) close downstream resources only AFTER drain
    clearTimeout(force);
    process.exit(0); // clean
  } catch (err) {
    console.error('shutdown error', err);
    process.exit(1);
  }
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

Why it's right: readiness flips first so the LB deregisters before you stop accepting (closes the race); server.close() drains in-flight requests instead of killing them (no 502s); the pool closes only after drain so finishing requests don't hit a dead connection; the idempotent guard survives a repeated signal; and the unref'd timeout below the grace period guarantees you exit on your own terms with a log line instead of being SIGKILLed (137). Never call process.exit() before the drain awaits resolve — that truncates in-flight commits.

model.ru:
Зарегистрируй обработчик SIGTERM/SIGINT, который выключает readiness, сливает, затем выходит под жёстким таймаутом:

let shuttingDown = false;
async function shutdown(sig) {
  if (shuttingDown) return; // идемпотентно: 2-й SIGTERM не должен войти повторно
  shuttingDown = true;
  console.log(`${sig}: draining`);

  ready = false; // (a) выключи readiness ПЕРВЫМ, чтобы LB перестал слать новый трафик

  const force = setTimeout(() => {
    console.error('drain timed out, forcing exit');
    process.exit(1);
  }, 10_000);
  force.unref(); // сам таймер не должен держать цикл живым

  try {
    await new Promise((res, rej) =>
      server.close((err) => (err ? rej(err) : res())) // (b) перестань принимать, дай полёту завершиться
    );
    await pool.end(); // (c) закрывай ресурсы ниже по потоку только ПОСЛЕ слива
    clearTimeout(force);
    process.exit(0); // чисто
  } catch (err) {
    console.error('shutdown error', err);
    process.exit(1);
  }
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

Почему верно: readiness выключается первым, чтобы LB снял с ротации до того, как ты перестанешь принимать (закрывает гонку); server.close() сливает запросы в полёте, а не убивает их (нет 502); пул закрывается только после слива, чтобы дозавершающиеся запросы не упёрлись в мёртвое соединение; идемпотентная защита переживает повторный сигнал; а unref-нутый таймаут ниже grace-периода гарантирует выход на своих условиях со строкой лога вместо SIGKILL (137). Никогда не вызывай process.exit() до того, как слив дорезолвится, — это обрезает коммиты в полёте.
